<section class="page container"><div class="page-title"><div><span class="eyebrow">Temukan pilihan terbaik</span><h1>Cari Mobil</h1><p><?= count($cars) ?> mobil ditemukan</p></div></div><form class="filters" method="get"><input name="q" value="<?= e($filters['q']??'') ?>" placeholder="Merek, model, atau kota"><select name="brand"><option value="">Semua merek</option><?php foreach(['Toyota','Honda','Daihatsu','Suzuki','Mitsubishi','Hyundai','BMW','Mercedes-Benz'] as $b): ?><option <?= ($filters['brand']??'')===$b?'selected':'' ?>><?= $b ?></option><?php endforeach; ?></select><select name="transmission"><option value="">Semua transmisi</option><option>Manual</option><option>Otomatis</option></select><input type="number" name="min" value="<?= e($filters['min']??'') ?>" placeholder="Harga minimum"><input type="number" name="max" value="<?= e($filters['max']??'') ?>" placeholder="Harga maksimum"><select name="sort"><option value="newest">Terbaru</option><option value="price_asc">Harga terendah</option><option value="price_desc">Harga tertinggi</option><option value="year">Tahun terbaru</option></select><button class="btn btn-primary">Terapkan</button></form><?php if($cars): ?><div class="cards"><?php foreach($cars as $car) require __DIR__.'/card.php'; ?></div><?php else: ?><div class="empty"><div>🔎</div><h2>Mobil belum ditemukan</h2><p>Coba ubah kata kunci atau rentang harga.</p></div><?php endif; ?></section>
